import{z as r,x as l,o as A,c as s,q as e,j as B,D as a,d as o,s as i,S as n}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"ISDA 与文档体系","description":"","frontmatter":{"title":"ISDA 与文档体系","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ot-isda-documentation.md","filePath":"quant/ot-isda-documentation.md","lastUpdated":1791063341000}'),d={name:"quant/ot-isda-documentation.md"};function u(D,E,p,C,c,m){const t=l("Mermaid");return A(),s("div",null,[E[2]||(E[2]=e('<h1 id="isda-与文档体系" tabindex="-1">ISDA 与文档体系 <a class="header-anchor" href="#isda-与文档体系" aria-label="Permalink to &quot;ISDA 与文档体系&quot;">​</a></h1><div class="epigraph"><p>场外衍生品没有中央化的合约：净额与抵押不是会计惯例，是写在主协议里的法律构造；文档缺一格，风险模型里就多一行没人认领的暴露。</p><footer>—— 据 ISDA 1992/2002 年主协议文本与 1994/2016 年信用支持附件整理</footer></div><p><a href="/quant/ot-issuer-hedging">上一课</a>把发行台的对冲写成日常运作，但每一条对冲腿、每一笔保证金、每一次终止，都长在合同上。本课进入法律层：主协议、附件、确认书与信用支持文件如何把净额结算变成可执行的权利。前课反复出现的两个词在此落地——「净额集」从哪里取得法律效力，对消凭什么不能跨对手。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两万笔互换与期权，逐笔独立看是两万张合同；违约时清算人若可以挑拣履约（cherry-picking），正市值留给你、负市值终止掉，净额不存在，抵押的根基也不存在。缺口是法律构造：必须让全部交易在违约时被视为一份合同的终止，且这一构造在对手所在司法辖区可执行。文档缺口的另一面同样真实：确认书晚到、条款字段与定价系统不一致、障碍时钟在确认书里与台账里写得不一致——定价认为的对消，法庭上不成立。</p><p><span class="marginnote">术语翻译：cherry-picking（挑拣履约）就是清算人当挑剔的买家——对你有利（欠你钱）的合同宣布作废，对你不利（你欠钱）的合同照常执行。单一协议条款的全部意义，就是堵死这种挑法。</span></p>',6)),(A(),B(n,null,{default:a(()=>[i(t,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEF%5B%22%E5%AF%B9%E6%89%8B%E8%BF%9D%E7%BA%A6%EF%BC%9A%E6%8C%81%E6%9C%89N%E7%AC%94%E4%BA%A4%E6%98%93%22%5D%20--%3E%20A%5B%22%E6%97%A0%E5%8D%95%E4%B8%80%E5%8D%8F%E8%AE%AE%EF%BC%9A%E9%80%90%E7%AC%94%E6%B8%85%E7%AE%97%22%5D%0A%20%20DEF%20--%3E%20B%5B%22%E5%8D%95%E4%B8%80%E5%8D%8F%E8%AE%AE%EF%BC%9A%E6%95%B4%E4%BD%93%E7%BB%88%E6%AD%A2%22%5D%0A%20%20A%20--%3E%20A1%5B%22%E6%B8%85%E7%AE%97%E4%BA%BA%E6%8C%91%E6%8B%A3%E5%B1%A5%E7%BA%A6%22%5D%0A%20%20A1%20--%3E%20A2%5B%22%E6%AD%A3%E5%80%BC%E5%AF%B9%E5%86%B2%E8%A2%AB%E4%BD%9C%E5%BA%9F%20%E8%B4%9F%E5%80%BC%E4%B9%89%E5%8A%A1%E4%BF%9D%E7%95%99%22%5D%0A%20%20B%20--%3E%20B1%5B%22%E5%85%A8%E9%83%A8%E4%BA%A4%E6%98%93%E5%B9%B6%E5%85%A5%E5%87%80%E9%A2%9D%E9%9B%86%22%5D%0A%20%20B1%20--%3E%20B2%5B%22%E5%8F%AA%E7%BB%93%E4%B8%80%E4%B8%AA%E7%BB%88%E6%AD%A2%E5%87%80%E9%A2%9D%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[o(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>主协议三层：主协议本体（Master）写终止、违约事件与净额机制，跨交易一次性签署；附表（Schedule）改默认条款——适用法律、自动提前终止与否、交叉违约门槛；确认书（Confirmation）逐笔写经济条款。结构化产品的确认书字段即<a href="/quant/ot-autocall-snowball-deep">雪球深化</a>的字段表：障碍水平、观察时钟、日历与调整惯例逐格对上台账，这是「条款即价格」的合同面。信用支持文件（CSA）独立签署：合格抵押品清单、估值折扣、独立金额与阈值、争议解决与补仓频率——暴露剖面课里 CSA 的每个参数都对应这里的合同字段。</p> \\[\\text{终止净额}=\\max\\Bigl(\\sum_i V_i,\\,0\\Bigr)\\quad\\text{而非}\\quad\\sum_i \\max(V_i,0) \\]<p><span class="marginnote">1992 年版主协议用 Market Quotation（询第三方报价定终止额），1998 年俄罗斯违约期间市场报价不可得，机制失灵；2002 年版改为 Close-out Amount，由守约方按商业合理原则自行确定。中国 2022 年施行的《期货和衍生品法》写明终止净额结算不因单一交易违约而整体无效，净额的可执行性由此在立法层面落地。</span></p><p><span class="marginnote">数字实例：违约时与对手有 3 笔交易，市值 +500 万、−300 万、+200 万。逐笔清算，两笔正值只能各自主张 700 万，负的 300 万照样要付；终止净额只有一个数：\\(\\max(400\\text{万},0)=400\\) 万。两式相差的 300 万，就是「单一协议」这条法律构造的直接标价。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>净额的机制核心是单一协议条款：全部交易构成一份协议，违约时一并按终止净额清算。它是风险的，因为各司法辖区的破产法不同——有些法域承认主协议与净额，有些对特定交易设强制留置。法律意见登记簿（netting opinions）因此是净额集的一部分：对某个对手所在法域没有有效意见，其交易在监管口径里不得并入净额集，<a href="/quant/cva-exposure-profile">暴露剖面</a>的聚合单位随之改变。抵押的机制是降暴露而不是消除暴露：CSA 把当前暴露压到阈值附近，风险迁往保证金期内的跳价与抵押品本身的缺口——「有 CSA 故信用风险为零」在 2008 年已经失效，<a href="/quant/rc-collateral-funding">抵押与资金链</a>的折价螺旋是它的市场面。</p><p><span class="marginnote">常见误区：签了 CSA 就当信用风险归零。CSA 只把日常暴露压到阈值附近，从对手违约到补足抵押之间还有几天保证金期，市场可以跳价；抵押品本身还有折价与法律隔离问题——2008 年「有抵押」的大账本同样出了大洞。</span></p>',8)),(A(),B(n,null,{default:a(()=>[i(t,{id:"mermaid-39",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E4%B8%BB%E5%8D%8F%E8%AE%AE%20Master%EF%BC%9A%E7%BB%88%E6%AD%A2%E4%B8%8E%E5%87%80%E9%A2%9D%E6%9C%BA%E5%88%B6%22%5D%20--%3E%20S%5B%22%E9%99%84%E8%A1%A8%20Schedule%EF%BC%9A%E6%B3%95%E5%9F%9F%E4%B8%8E%E9%97%A8%E6%A7%9B%22%5D%0A%20%20S%20--%3E%20C%5B%22%E7%A1%AE%E8%AE%A4%E4%B9%A6%20Confirmation%EF%BC%9A%E9%80%90%E7%AC%94%E7%BB%8F%E6%B5%8E%E6%9D%A1%E6%AC%BE%22%5D%0A%20%20M%20--%3E%20CSA%5B%22%E4%BF%A1%E7%94%A8%E6%94%AF%E6%8C%81%E9%99%84%E4%BB%B6%20CSA%EF%BC%9A%E6%8A%B5%E6%8A%BC%E3%80%81%E9%98%88%E5%80%BC%E3%80%81%E6%8A%98%E6%89%A3%22%5D%0A%20%20C%20--%3E%20F%5B%22%E5%AD%97%E6%AE%B5%E5%AF%B9%E9%BD%90%E5%8F%B0%E8%B4%A6%EF%BC%9A%E9%9A%9C%E7%A2%8D%E6%B0%B4%E5%B9%B3%E4%B8%8E%E6%97%B6%E9%92%9F%22%5D%0A%20%20F%20--%3E%20N%5B%22%E5%87%80%E9%A2%9D%E9%9B%86%EF%BC%9A%E6%9A%B4%E9%9C%B2%E8%81%9A%E5%90%88%E7%9A%84%E6%B3%95%E5%BE%8B%E5%8D%95%E4%BD%8D%22%5D%0A%20%20CSA%20--%3E%20N%0A%20%20N%20--%3E%20X%5B%22%E5%AF%B9%E6%89%8B%E4%BF%A1%E7%94%A8%E7%AE%A1%E7%90%86%EF%BC%9APD%20%E4%B9%98%20EE%20%E4%B9%98%20LGD%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[o(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课是工程口径不是法律意见：具体交易的法律有效性取决于法域与文本，净额意见由法务出具并登记。不展开违约后的处置与拍卖机制——那是下一课对手方信用管理的入口。定义文件（利率、股本、大宗）只点名：<a href="/quant/multi-curve-ois">多曲线与 OIS</a>课已经见过指数退场如何改写曲线的合同地位，定义文件的修订与确认书的 fallback 是同一机制在文档层的样子。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>场外的净额与抵押是法律构造：单一协议条款使终止净额成立，效力逐法域确认并登记。</li><li>文档三层分工：主协议管机制、附表管法域与门槛、确认书管逐笔条款；CSA 管抵押。</li><li>确认书字段必须与定价台账对齐，障碍水平与观察时钟尤其如此。</li><li>Market Quotation 在 1998 失灵促成 2002 Close-out Amount；净额可执行性有赖立法与判例。</li><li>出处：ISDA 主协议与信用支持附件文本；《期货和衍生品法》（2022）；暴露与抵押的量化口径沿 <a href="/quant/cva-exposure-profile">CVA 暴露剖面</a>与<a href="/quant/rc-collateral-funding">抵押与资金链</a>。</li></ul>',4))])}const f=r(d,[["render",u]]);export{h as __pageData,f as default};
